            kl("\u0627\u0644\u062d\u0644\u0645 \u0645\u0639 \u0627\u0644\u0634\u062c\u0627\u0639\u0629\u061b \u0641\u0627\u0644\u062d\u0633\u0646 \u0643\u0627\u0646 \u0634\u062c\u0627\u0639\u0627\u064b \u0641\u064a \u0627\u0644\u062d\u0631\u0628 \u062d\u0644\u064a\u0645\u0627\u064b \u0641\u064a \u0627\u0644\u0635\u0644\u062d\u060c ", YD, " \u0648\u064a\u064f\u0633\u062a\u0641\u0627\u062f \u0645\u0646\u0647 \u0636\u0628\u0637 \u0627\u0644\u063a\u0636\u0628 \u062d\u064a\u0646 \u064a\u064f\u0631\u0627\u062f \u0627\u0644\u062d\u0642\u061b ", IQ, "."),
