seed_path = Path("/workspace/artifacts/majalis/src/lib/islamic-stories-seed.ts")
text = seed_path.read_text(encoding="utf-8")
for s in stories:
    pattern = rf"  \{{\n    id: {s['id']},[\s\S]*?\n  \}}"
    repl = render(s)
    new_text, n = re.subn(pattern, repl, text, count=1)
    if n != 1:
        raise SystemExit(f"Failed to replace id {s['id']}, matches={n}")
    text = new_text
seed_path.write_text(text, encoding="utf-8")
